# 2026-10-27 (расследование «ИИ мобилки не отвечает в переписке»): понятные причины вместо «не ответил», последняя ошибка в «Ключи Gemini».
S.update({
    "advisorQuota": ("Лимит ИИ исчерпан до {time} (общий с кассой и ботом). Можно добавить второй ключ из другого аккаунта Google.", "ИИ лимити {time} чейин түгөндү (касса жана бот менен жалпы). Башка Google аккаунтунан экинчи ачкыч кошсоңуз болот.", "AI limit used up until {time} (shared with the till and the bot). You can add a second key from another Google account.", "YZ limiti {time} saatine kadar doldu (kasa ve botla ortak). Başka bir Google hesabından ikinci bir anahtar ekleyebilirsiniz.", "SI limiti soat {time} gacha tugadi (kassa va bot bilan umumiy). Boshqa Google akkauntidan ikkinchi kalit qo'shishingiz mumkin."),
    "advisorQuotaLater": ("Лимит ИИ исчерпан (общий с кассой и ботом). Попробуйте позже или добавьте второй ключ из другого аккаунта Google.", "ИИ лимити түгөндү (касса жана бот менен жалпы). Кийинчерээк аракет кылыңыз же башка Google аккаунтунан экинчи ачкыч кошуңуз.", "AI limit used up (shared with the till and the bot). Try later or add a second key from another Google account.", "YZ limiti doldu (kasa ve botla ortak). Daha sonra deneyin veya başka bir Google hesabından ikinci bir anahtar ekleyin.", "SI limiti tugadi (kassa va bot bilan umumiy). Keyinroq urinib ko'ring yoki boshqa Google akkauntidan ikkinchi kalit qo'shing."),
    "advisorKeyRejected": ("Google отклонил ключ, повтор после {time}. Проверьте ключ в «Настройка ИИ» → «Ключи Gemini».", "Google ачкычты четке какты, {time} кийин кайра аракет болот. Ачкычты «ИИ жөндөөсү» → «Gemini ачкычтары» бөлүмүндө текшериңиз.", "Google rejected the key, retry after {time}. Check the key in “AI settings” → “Gemini keys”.", "Google anahtarı reddetti, {time} sonrasında tekrar denenecek. Anahtarı “Yapay zekâ ayarları” → “Gemini anahtarları” bölümünde kontrol edin.", "Google kalitni rad etdi, {time} dan keyin qayta uriniladi. Kalitni «SI sozlamalari» → «Gemini kalitlari» bo'limida tekshiring."),
    "advisorTimeout": ("ИИ долго не отвечает. Проверьте интернет и нажмите «Повторить».", "ИИ узак убакыт жооп бербей жатат. Интернетти текшерип, «Кайталоо» баскычын басыңыз.", "The AI is taking too long to answer. Check the internet and tap “Retry”.", "YZ uzun süredir yanıt vermiyor. İnterneti kontrol edip “Tekrar dene”ye dokunun.", "SI uzoq vaqt javob bermayapti. Internetni tekshirib, «Qayta urinish»ni bosing."),
    "gkLastError": ("Последняя ошибка: {text}", "Акыркы ката: {text}", "Last error: {text}", "Son hata: {text}", "Oxirgi xato: {text}"),
    "aiAccOwnerNote": ("Вас нет в списке, но владельцу и администратору ИИ доступен всегда.", "Сиз тизмеде жоксуз, бирок ээсине жана администраторго ИИ дайыма жеткиликтүү.", "You are not in the list, but the owner and the administrator can always use AI.", "Listede değilsiniz, ancak sahibi ve yönetici YZ'yi her zaman kullanabilir.", "Siz ro'yxatda yo'qsiz, lekin egasi va administrator SI dan doim foydalana oladi."),
})

# 2026-10-27 (аудит мобилки 27.10, исправления): подтверждение аномальной цены, подсказки «касса не найдена»/отказ, ИИ-тексты.
S.update({
    "pePriceCheckTitle": ("Проверьте цену", "Бааны текшериңиз", "Check the price", "Fiyatı kontrol edin", "Narxni tekshiring"),
    "pePriceUpAsk": ("Цена {now} вместо {was} — сохранить?\nЭто в {times} раз больше прежней.", "Баа {was} эмес, {now} — сактайсызбы?\nМурдагыдан {times} эсе көп.", "Price {now} instead of {was} — save?\nThat is {times}× the old price.", "Fiyat {was} yerine {now} — kaydedilsin mi?\nEski fiyatın {times} katı.", "Narx {was} o'rniga {now} — saqlansinmi?\nAvvalgisidan {times} baravar ko'p."),
    "pePriceDownAsk": ("Цена {now} вместо {was} — сохранить?\nЭто в {times} раз меньше прежней.", "Баа {was} эмес, {now} — сактайсызбы?\nМурдагыдан {times} эсе аз.", "Price {now} instead of {was} — save?\nThat is {times}× lower than the old price.", "Fiyat {was} yerine {now} — kaydedilsin mi?\nEski fiyatın {times} kat altında.", "Narx {was} o'rniga {now} — saqlansinmi?\nAvvalgisidan {times} baravar kam."),
    "peBelowCostAsk": ("Цена {now} ниже закупки {cost} — продажа в убыток. Сохранить?", "Баа {now} сатып алуудан {cost} төмөн — зыянга сатуу. Сактайсызбы?", "Price {now} is below the purchase price {cost} — selling at a loss. Save?", "Fiyat {now}, alış fiyatı {cost} altında — zararına satış. Kaydedilsin mi?", "Narx {now} xarid narxi {cost} dan past — zararga sotish. Saqlansinmi?"),
    "peMarkupAsk": ("Цена {now} при закупке {cost}: наценка {pct} %. Нет ли ошибки в цифрах? Сохранить?", "Баа {now}, сатып алуу {cost}: үстөк {pct} %. Сандарда ката жокпу? Сактайсызбы?", "Price {now} with purchase price {cost}: markup {pct} %. Is there a typo in the numbers? Save?", "Fiyat {now}, alış {cost}: kâr {pct} %. Rakamlarda hata var mı? Kaydedilsin mi?", "Narx {now}, xarid {cost}: ustama {pct} %. Raqamlarda xato yo'qmi? Saqlansinmi?"),
    "peFixPrice": ("Исправить", "Оңдоо", "Fix it", "Düzelt", "Tuzatish"),
    "peSaveAsIs": ("Сохранить как есть", "Ушундай сактоо", "Save as is", "Olduğu gibi kaydet", "Shunday saqlash"),
    "klSearching": ("Ищу кассу в сети Wi-Fi…", "Кассаны Wi-Fi тармагында издеп жатам…", "Looking for the till on Wi-Fi…", "Kasa Wi-Fi ağında aranıyor…", "Kassa Wi-Fi tarmog'ida qidirilmoqda…"),
    "klHelpNotFound": ("Касса не отвечает. Проверьте: 1) касса запущена; 2) в настройках кассы включено «Принимать сканы с телефонов» (по умолчанию оно выключено); 3) телефон в той же Wi-Fi сети, что и компьютер с кассой, а не на мобильном интернете.", "Касса жооп бербей жатат. Текшериңиз: 1) касса иштеп жатабы; 2) кассанын жөндөөлөрүндө «Телефондордон сканерлөөнү кабыл алуу» күйгүзүлгөнбү (демейки боюнча өчүк); 3) телефон кассасы бар компьютер менен бир Wi-Fi тармагындабы, мобилдик интернетте эмес.", "The till does not answer. Check: 1) the till is running; 2) “Accept scans from phones” is turned on in the till settings (it is off by default); 3) the phone is on the same Wi-Fi network as the till computer, not on mobile data.", "Kasa yanıt vermiyor. Kontrol edin: 1) kasa çalışıyor mu; 2) kasa ayarlarında “Telefonlardan taramaları kabul et” açık mı (varsayılan olarak kapalıdır); 3) telefon, kasa bilgisayarıyla aynı Wi-Fi ağında mı, mobil veride değil.", "Kassa javob bermayapti. Tekshiring: 1) kassa ishlayaptimi; 2) kassa sozlamalarida «Telefonlardan skanerlashni qabul qilish» yoqilganmi (odatda o'chiq); 3) telefon kassali kompyuter bilan bir Wi-Fi tarmog'idami, mobil internetda emas."),
    "klHelpDisabled": ("На кассе выключен приём с телефонов. Включите «Принимать сканы с телефонов» в настройках кассы и нажмите «Проверить связь».", "Кассада телефондордон кабыл алуу өчүк. Кассанын жөндөөлөрүндө «Телефондордон сканерлөөнү кабыл алуу» күйгүзүп, «Байланышты текшерүү» баскычын басыңыз.", "Receiving from phones is off on the till. Turn on “Accept scans from phones” in the till settings and tap “Check the link”.", "Kasada telefonlardan kabul kapalı. Kasa ayarlarında “Telefonlardan taramaları kabul et”i açıp “Bağlantıyı kontrol et”e dokunun.", "Kassada telefonlardan qabul o'chiq. Kassa sozlamalarida «Telefonlardan skanerlashni qabul qilish»ni yoqib, «Aloqani tekshirish»ni bosing."),
    "klHelpRePair": ("Касса не узнаёт этот телефон (его отключили или QR устарел). Нажмите «Сканировать QR заново» и наведите камеру на QR в окне «Подключить телефон» на кассе.", "Касса бул телефонду таныбай жатат (ал ажыратылган же QR эскирген). «QR кайра скандоо» баскычын басып, кассадагы «Телефонду туташтыруу» терезесиндеги QR кодго камераны багыттаңыз.", "The till does not recognise this phone (it was disconnected or the QR is outdated). Tap “Scan the QR again” and point the camera at the QR in the “Connect a phone” window on the till.", "Kasa bu telefonu tanımıyor (bağlantısı kesildi veya QR eskidi). “QR'ı yeniden tara”ya dokunup kamerayı kasadaki “Telefonu bağla” penceresindeki QR'a doğrultun.", "Kassa bu telefonni tanimayapti (u uzilgan yoki QR eskirgan). «QR-kodni qayta skanerlash»ni bosib, kameraini kassadagi «Telefonni ulash» oynasidagi QR-kodga qarating."),
    "klHelpBadTime": ("Время на телефоне и на кассе расходится больше чем на 10 минут. Включите автоматическую дату и время на телефоне (и проверьте время на кассе), затем нажмите «Проверить связь».", "Телефондогу жана кассадагы убакыт 10 мүнөттөн ашык айырмаланат. Телефондо датаны жана убакытты автоматтык кылыңыз (кассадагы убакытты да текшериңиз), анан «Байланышты текшерүү» баскычын басыңыз.", "The time on the phone and on the till differs by more than 10 minutes. Turn on automatic date and time on the phone (and check the time on the till), then tap “Check the link”.", "Telefon ile kasa saati arasında 10 dakikadan fazla fark var. Telefonda otomatik tarih ve saati açın (kasadaki saati de kontrol edin), sonra “Bağlantıyı kontrol et”e dokunun.", "Telefon va kassa vaqti o'rtasida 10 daqiqadan ortiq farq bor. Telefonda sana va vaqtni avtomatik qiling (kassadagi vaqtni ham tekshiring), keyin «Aloqani tekshirish»ni bosing."),
    "klRescanQr": ("Сканировать QR заново", "QR кодду кайра скандоо", "Scan the QR again", "QR'ı yeniden tara", "QR-kodni qayta skanerlash"),
    "klScRefused": ("Код не отправлен — сначала восстановите связь с кассой", "Код жөнөтүлгөн жок — адегенде кассага байланышты калыбына келтириңиз", "Code not sent — restore the link with the till first", "Kod gönderilmedi — önce kasayla bağlantıyı düzeltin", "Kod yuborilmadi — avval kassa bilan aloqani tiklang"),
    "aiAccDraftNote": ("Список ещё не сохранён: сейчас ИИ доступен всем сотрудникам. Отметьте до 2 человек и нажмите «Сохранить» — у остальных ИИ выключится. Владельцу и администратору ИИ доступен всегда.", "Тизме али сакталган жок: азыр ИИ бардык кызматкерлерге жеткиликтүү. 2 кишиге чейин белгилеп, «Сактоо» баскычын басыңыз — калгандарда ИИ өчөт. Ээсине жана администраторго ИИ дайыма жеткиликтүү.", "The list is not saved yet: right now AI is open to all employees. Tick up to 2 people and tap “Save” — AI will turn off for the rest. The owner and the administrator can always use AI.", "Liste henüz kaydedilmedi: şu anda YZ tüm çalışanlara açık. En fazla 2 kişiyi işaretleyip “Kaydet”e dokunun — diğerleri için YZ kapanır. Sahibi ve yönetici YZ'yi her zaman kullanabilir.", "Ro'yxat hali saqlanmagan: hozir SI barcha xodimlarga ochiq. 2 tagacha odamni belgilab, «Saqlash»ni bosing — qolganlarda SI o'chadi. Egasi va administrator SI dan doim foydalana oladi."),
    "aiAccAlways": ("Владельцу и администратору ИИ доступен всегда, независимо от списка.", "Ээсине жана администраторго ИИ тизмеге карабай дайыма жеткиликтүү.", "The owner and the administrator can always use AI, whatever the list says.", "Sahibi ve yönetici, listeden bağımsız olarak YZ'yi her zaman kullanabilir.", "Egasi va administrator ro'yxatdan qat'i nazar SI dan doim foydalana oladi."),
})

# 2026-10-27 (владелец: «в мобилке и в десктопе добавь возможность загрузки электронных накладных»): «Загрузить накладную»
