LANGS = ["ru", "ky", "en", "tr", "uz"]
INT_PARAMS = {"n", "a", "b"}
# 2026-10-26 (живой аудит, П0): целые параметры отдельных ключей (тип в .arb был задан руками, скрипт его не знал)
INT_PARAMS_BY_KEY = {"accountLoading": {"done", "total"}, "guardUnsent": {"n"}, "guardSendLeft": {"n"}, "guardForeign": {"n"}, "smartPartial": {"done", "total", "left"}, "vcInvoiceSummary": {"n", "known", "fresh"}, "aiLogUndoPartial": {"done", "total"}}

here = os.path.dirname(os.path.abspath(__file__))
out = os.path.join(here, "..", "lib", "l10n")
os.makedirs(out, exist_ok=True)
for i, lang in enumerate(LANGS):
    data = {"@@locale": lang}
    for key, texts in S.items():
        text = texts[i]
        data[key] = text
        params = re.findall(r"\{(\w+)\}", texts[0])
        if lang == "ru" and params:
            data["@" + key] = {"placeholders": {p: {"type": "int" if (p in INT_PARAMS or p in INT_PARAMS_BY_KEY.get(key, ())) else "String"} for p in dict.fromkeys(params)}}
    with io.open(os.path.join(out, f"app_{lang}.arb"), "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
print(f"{len(S)} keys x {len(LANGS)} languages")
